PRINCIPLES={
'Diagnostic accuracy':('Promote human well-being, safety and the public interest','Potentially at risk','Clinical validation gaps or unsafe reliance may expose patients to incorrect outputs',['Independent clinical validation','Define safety acceptance thresholds','Human confirmation for high-consequence decisions','Monitor false negatives and model drift'],'Clinical Safety / AI Product Owner'),
'Bias and health inequality':('Ensure inclusiveness and equity','Potentially at risk','Unequal model performance can disadvantage underrepresented patient groups',['Validate on intended population','Measure performance by relevant subgroup','Set fairness thresholds','Monitor disparities after deployment'],'Responsible AI / Clinical Safety'),
'Patient safety':('Promote human well-being, safety and the public interest','Potentially at risk','Outputs may create or amplify clinical harm without safety controls',['Clinical hazard analysis','Human oversight','Escalation and fail-safe rules','Incident reporting and rollback criteria'],'Clinical Safety Officer'),
'Privacy and data protection':('Protect autonomy','Potentially at risk','Sensitive health data may be collected, exposed or processed beyond intended purpose',['Data minimisation','DPIA/privacy assessment','Role-based access and encryption','Retention and deletion controls'],'Privacy / Data Protection'),
'Hallucination and misinformation':('Ensure transparency, explainability and intelligibility','Potentially at risk','AI-generated health information may be fabricated or insufficiently grounded',['Ground responses in approved clinical sources','Display uncertainty and limitations','Red-team harmful outputs','Escalate clinical advice to qualified humans'],'AI Product / Clinical Safety'),
'Transparency and explainability':('Ensure transparency, explainability and intelligibility','Potentially at risk','Users may be unable to understand intended use, limitations or basis of outputs',['Publish intended use and limitations','Model/system cards','Explain uncertainty','Test explanations with intended users'],'AI Governance'),
'Automation bias and oversight':('Protect autonomy','Potentially at risk','Humans may over-rely on AI recommendations or lack meaningful override mechanisms',['Document human decision rights','Provide override routes','Monitor overrides and disagreement','Train users on automation bias'],'Clinical Operations'),
'Dataset and model quality':('Foster responsibility and accountability','Potentially at risk','Poor data quality, representativeness or drift can degrade model performance',['Data quality controls','Dataset provenance','Drift and calibration monitoring','Version control and rollback'],'Model Risk / Data Governance'),
'Cybersecurity':('Foster responsibility and accountability','Potentially at risk','Compromise or manipulation may affect confidentiality, integrity or availability',['Threat modelling','Access control','Adversarial testing','Incident response and recovery testing'],'Cybersecurity'),
'Regulatory and legal':('Foster responsibility and accountability','Potentially at risk','Weak governance may create compliance, accountability or assurance gaps',['AI inventory and accountable owner','Regulatory applicability assessment','Audit trail','Incident and change governance'],'Compliance / AI Governance'),
'General AI governance risk':('Foster responsibility and accountability','Insufficient evidence','The signal requires additional analysis before assigning a specific governance implication',['Human review','Confirm AI use case','Identify affected stakeholders','Document applicable controls'],'AI Governance')}
def enrich(df):
 p=df['risk_category'].apply(lambda x: PRINCIPLES.get(x,PRINCIPLES['General AI governance risk']))
 df=df.copy(); df['governance_principle']=p.str[0]; df['principle_status']=p.str[1]; df['principle_rationale']=p.str[2]; df['recommended_mitigation']=p.str[3].apply(lambda x:'; '.join(x)); df['control_owner']=p.str[4]
 df['analyst_view']=df.apply(lambda r:f"This signal suggests that {r.governance_principle.lower()} may require attention if a similar {str(r.ai_use_case).lower()} use case exists in the organisation. Review the underlying evidence and test whether the listed controls are implemented and effective.",axis=1)
 df['analyst_confidence']=df.apply(lambda r:'High' if r.source_credibility_score>=4 and r.evidence_level=='Formal/confirmed finding' else 'Medium' if r.source_credibility_score>=3 else 'Low',axis=1)
 return df
